solution.code:
// Ubah "app/(toko)/produk/[id]/page.tsx" menjadi folder "app/(toko)/produk/[id]"
function folderDari(file) {
  return file.slice(0, file.lastIndexOf("/"));
}

function namaFile(file) {
  return file.slice(file.lastIndexOf("/") + 1).replace(/\.(t|j)sx?$/, "");
}

// Jenis segmen URL: 0 statis, 1 dinamis [id], 2 catch-all [...slug]
function jenisSegmen(seg) {
  if (seg.startsWith("[...") && seg.endsWith("]")) return { jenis: 2, nama: seg.slice(4, -1) };
  if (seg.startsWith("[") && seg.endsWith("]")) return { jenis: 1, nama: seg.slice(1, -1) };
  return { jenis: 0, nama: seg };
}

function cocokkan(pola, bagian) {
  const params = {};
  for (let i = 0; i < pola.length; i++) {
    const s = pola[i];
    if (s.jenis === 2) {
      const sisa = bagian.slice(i);
      if (sisa.length === 0) return null;
      params[s.nama] = sisa;
      return params;
    }
    if (i >= bagian.length) return null;
    if (s.jenis === 1) params[s.nama] = bagian[i];
    else if (s.nama !== bagian[i]) return null;
  }
  return pola.length === bagian.length ? params : null;
}

// Bandingkan dua route: segmen statis menang dari dinamis, dinamis menang dari catch-all
function lebihSpesifik(a, b) {
  const n = Math.max(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const ja = a[i] ? a[i].jenis : 3;
    const jb = b[i] ? b[i].jenis : 3;
    if (ja !== jb) return ja - jb;
  }
  return 0;
}

function buatRouter(files, meta = {}) {
  const layoutDi = {};
  const pages = [];
  let notFound = null;
  for (const file of files) {
    const nama = namaFile(file);
    const folder = folderDari(file);
    if (nama === "layout") layoutDi[folder] = file;
    else if (nama === "not-found" && folder === "app") notFound = file;
    else if (nama === "page") {
      const segmen = folder.split("/").slice(1).filter((s) => !(s.startsWith("(") && s.endsWith(")")));
      pages.push({ file, folder, pola: segmen.map(jenisSegmen) });
    }
  }
  pages.sort((a, b) => lebihSpesifik(a.pola, b.pola));

  function layoutsUntuk(folder) {
    const hasil = [];
    const bagian = folder.split("/");
    for (let i = 1; i <= bagian.length; i++) {
      const f = bagian.slice(0, i).join("/");
      if (layoutDi[f]) hasil.push(layoutDi[f]);
    }
    return hasil;
  }

  function resolve(url) {
    const path = url.split("?")[0].split("#")[0];
    const bagian = path.split("/").filter(Boolean);
    for (const p of pages) {
      const params = cocokkan(p.pola, bagian);
      if (params) return { page: p.file, layouts: layoutsUntuk(p.folder), params };
    }
    return { page: notFound, layouts: layoutsUntuk("app"), params: {} };
  }

  function generateMetadata(url) {
    const r = resolve(url);
    let template = null;
    let judulDefault = null;
    let title = null;
    const hasil = {};
    for (const file of [...r.layouts, r.page]) {
      const sumber = meta[file];
      if (!sumber) continue;
      const m = typeof sumber === "function" ? sumber(r.params) : sumber;
      for (const [k, v] of Object.entries(m)) {
        if (k !== "title") hasil[k] = v;
      }
      if (m.title && typeof m.title === "object") {
        if (m.title.template) template = m.title.template;
        if (m.title.default) judulDefault = m.title.default;
        title = null;
      } else if (typeof m.title === "string") {
        title = template ? template.replace("%s", m.title) : m.title;
      }
    }
    hasil.title = title ?? judulDefault ?? "";
    return hasil;
  }

  return { resolve, generateMetadata };
}

