solution.code:
const KATA_RAHASIA = ["SECRET", "PASSWORD", "TOKEN", "KEY", "DATABASE"];

function envAman(nama) {
  const besar = nama.toUpperCase();
  if (!besar.startsWith("NEXT_PUBLIC_")) return true;
  return !KATA_RAHASIA.some((k) => besar.includes(k));
}

function envUntukBrowser(env) {
  const hasil = {};
  for (const [nama, nilai] of Object.entries(env)) {
    if (nama.startsWith("NEXT_PUBLIC_")) hasil[nama] = nilai;
  }
  return hasil;
}

