solution.code:
const BATAS = { lcp: [2500, 4000], inp: [200, 500], cls: [0.1, 0.25] };
const URUTAN = ["baik", "perlu perbaikan", "buruk"];

function label(nilai, [baik, buruk]) {
  if (nilai <= baik) return "baik";
  if (nilai <= buruk) return "perlu perbaikan";
  return "buruk";
}

function skorVitals(metrik) {
  const hasil = {};
  for (const k of ["lcp", "inp", "cls"]) hasil[k] = label(metrik[k], BATAS[k]);
  hasil.total = URUTAN[Math.max(...["lcp", "inp", "cls"].map((k) => URUTAN.indexOf(hasil[k])))];
  return hasil;
}
